<?php $rows=$pdo->query('SELECT t.*,u.unit_code FROM tire_inspections t JOIN units u ON u.id=t.unit_id ORDER BY inspection_date DESC')->fetchAll();$units=$pdo->query('SELECT id,unit_code FROM units ORDER BY unit_code')->fetchAll();?>
<div class="card panel"><h3>Input Inspeksi Ban</h3><form class="form-grid compact" method="post" action="actions/save_tire.php"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><label>Unit<select name="unit_id"><?php foreach($units as $u):?><option value="<?=$u['id']?>"><?=e($u['unit_code'])?></option><?php endforeach;?></select></label><label>Tanggal<input type="date" name="inspection_date" value="<?=date('Y-m-d')?>"></label><label>Posisi Ban<input name="tire_position" required></label><label>Tekanan PSI<input type="number" step="0.1" name="pressure_psi"></label><label>Kedalaman Tapak mm<input type="number" step="0.1" name="tread_depth_mm"></label><label>Kondisi<select name="condition_status"><?php foreach(['Baik','Perlu Rotasi','Aus Tidak Rata','Tipis','Harus Diganti'] as $s):?><option><?=$s?></option><?php endforeach;?></select></label><label>Catatan<input name="notes"></label><div><button class="btn primary">Simpan</button></div></form></div>
<div class="card panel"><h3>Riwayat Inspeksi Ban</h3><table><thead><tr><th>Tanggal</th><th>Unit</th><th>Posisi</th><th>PSI</th><th>Tapak</th><th>Kondisi</th><th>Catatan</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['inspection_date'])?></td><td><?=e($r['unit_code'])?></td><td><?=e($r['tire_position'])?></td><td><?=e((string)$r['pressure_psi'])?></td><td><?=e((string)$r['tread_depth_mm'])?> mm</td><td><span class="status <?=status_class($r['condition_status'])?>"><?=e($r['condition_status'])?></span></td><td><?=e($r['notes'])?></td></tr><?php endforeach;?></tbody></table></div>
